Form instance

```php
$form = FormBuilder::make()
            ->fields($fields)
            ->fillCast($item, $this->getModelCast());
```

Use in controller

```php
$form->apply(fn(Model $item) => $item->save());
```


A difficult example with all the features from the ModelResource

```php
$form->apply(
                static fn(Model $item) => $item->save(),
                default: fn(Field $field) => $this->onSave($field),
                before: function (Model $item) {
                    if (! $item->exists) {
                        $item = $this->beforeCreating($item);
                    }

                    if ($item->exists) {
                        $item = $this->beforeUpdating($item);
                    }

                    return $item;
                },
                after: function (Model $item) {
                    $wasRecentlyCreated = $item->wasRecentlyCreated;

                    $item->save();

                    if ($wasRecentlyCreated) {
                        $item = $this->afterCreated($item);
                    }

                    if (! $wasRecentlyCreated) {
                        $item = $this->afterUpdated($item);
                    }

                    return $item;
                },
                throw: true
            );
```

Script:
```javascript
const projectArr = require("./data.json");
const { mkdir, writeFile } = require("fs/promises");

async function main() {
  for (const project of projectArr) {
    const projectPath = `./projects/${project.slug}`;
    const path = `${projectPath}/${project.slug}.json`;
    await mkdir(projectPath, { recursive: true });
    await writeFile(path, JSON.stringify(project, null, 2));
  }
}

main()
  .then((res) => {
   console.log(res);
  })
  .catch((error) => {
   console.log(error);
  });

```

